import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ref, onValue, update } from 'firebase/database';
import { db } from '../firebase';

function EditSeries() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [seriesData, setSeriesData] = useState({
    title: '',
    totalSeasons: '',
    episodesPerSeason: '',
    currentSeason: '',
    currentEpisode: '',
    watchingTogether: true,
    coverImage: ''
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const seriesRef = ref(db, `series/${id}`);
    const unsubscribe = onValue(seriesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setSeriesData({
          title: data.title || '',
          totalSeasons: data.totalSeasons || '',
          episodesPerSeason: data.episodesPerSeason || '',
          currentSeason: data.currentSeason || '',
          currentEpisode: data.currentEpisode || '',
          watchingTogether: data.watchingTogether || false,
          coverImage: data.coverImage || ''
        });
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const seriesRef = ref(db, `series/${id}`);
      await update(seriesRef, {
        ...seriesData,
        totalSeasons: parseInt(seriesData.totalSeasons),
        episodesPerSeason: parseInt(seriesData.episodesPerSeason),
        currentSeason: parseInt(seriesData.currentSeason),
        currentEpisode: parseInt(seriesData.currentEpisode)
      });
      alert('Dizi başarıyla güncellendi!');
      navigate(`/series/${id}`);
    } catch (error) {
      console.error('Error updating series: ', error);
      alert('Dizi güncellenirken bir hata oluştu.');
    }
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSeriesData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  if (loading) {
    return (
      <div className="text-center">
        <p className="text-xl">Yükleniyor...</p>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto bg-white rounded-lg shadow-md p-8">
      <h2 className="text-2xl font-bold text-purple-600 mb-6">Dizi Düzenle</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-gray-700 mb-2">Dizi Adı</label>
          <input
            type="text"
            name="title"
            value={seriesData.title}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Kapak Fotoğrafı URL</label>
          <input
            type="url"
            name="coverImage"
            value={seriesData.coverImage}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            placeholder="https://example.com/image.jpg"
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Toplam Sezon Sayısı</label>
          <input
            type="number"
            name="totalSeasons"
            value={seriesData.totalSeasons}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Sezon Başına Bölüm Sayısı</label>
          <input
            type="number"
            name="episodesPerSeason"
            value={seriesData.episodesPerSeason}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Mevcut Sezon</label>
          <input
            type="number"
            name="currentSeason"
            value={seriesData.currentSeason}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div>
          <label className="block text-gray-700 mb-2">Mevcut Bölüm</label>
          <input
            type="number"
            name="currentEpisode"
            value={seriesData.currentEpisode}
            onChange={handleChange}
            className="w-full p-2 border rounded-lg"
            required
          />
        </div>
        <div className="flex items-center">
          <input
            type="checkbox"
            name="watchingTogether"
            checked={seriesData.watchingTogether}
            onChange={handleChange}
            className="mr-2"
          />
          <label className="text-gray-700">Birlikte İzliyoruz</label>
        </div>
        <div className="flex space-x-4">
          <button
            type="submit"
            className="flex-1 bg-purple-600 text-white py-2 px-4 rounded-lg hover:bg-purple-700 transition duration-200"
          >
            Kaydet
          </button>
          <button
            type="button"
            onClick={() => navigate(`/series/${id}`)}
            className="flex-1 bg-gray-500 text-white py-2 px-4 rounded-lg hover:bg-gray-600 transition duration-200"
          >
            İptal
          </button>
        </div>
      </form>
    </div>
  );
}

export default EditSeries;
